<?php require_once __DIR__.'/../includes/db.php';
$token=(string)($_GET['token']??'');$download=(int)($_GET['download']??0);$s=db()->prepare('SELECT ds.*,cp.project_name FROM construction_document_shares ds JOIN construction_projects cp ON cp.id=ds.construction_project_id WHERE ds.token=? AND ds.revoked_at IS NULL AND ds.expires_at>NOW()');$s->execute([$token]);$share=$s->fetch();if(!$share){http_response_code(404);exit('This document link is invalid or has expired.');}db()->prepare('UPDATE construction_document_shares SET first_opened_at=COALESCE(first_opened_at,NOW()),last_opened_at=NOW() WHERE id=?')->execute([$share['id']]);$q=db()->prepare('SELECT d.* FROM construction_document_share_items si JOIN construction_documents d ON d.id=si.document_id WHERE si.share_id=?');$q->execute([$share['id']]);$docs=$q->fetchAll();if($download){foreach($docs as $d){if((int)$d['id']!==$download)continue;$path=__DIR__.'/../'.$d['file_path'];if(!is_file($path))break;db()->prepare('UPDATE construction_document_shares SET download_count=download_count+1,last_opened_at=NOW() WHERE id=?')->execute([$share['id']]);header('Content-Type: '.($d['mime_type']?:'application/octet-stream'));header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.str_replace('"','',$d['original_name']).'"');readfile($path);exit;}http_response_code(404);exit('File not found.');}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Shared Documents</title><style>body{font-family:Arial;background:#f4f7f9;color:#172333;margin:0}.wrap{max-width:820px;margin:50px auto;padding:20px}.card{background:#fff;border:1px solid #dbe4eb;border-radius:12px;padding:24px;margin-bottom:14px}.btn{display:inline-block;background:#1e5c8f;color:#fff;text-decoration:none;padding:10px 14px;border-radius:7px}.muted{color:#6b7785}</style></head><body><div class="wrap"><div class="card"><h1><?=htmlspecialchars($share['project_name'])?></h1><p><?=nl2br(htmlspecialchars($share['message_text']?:'Project documents have been shared with you.'))?></p><p class="muted">This secure link expires <?=date('M j, Y g:i A',strtotime($share['expires_at']))?>.</p></div><?php foreach($docs as $d):?><div class="card"><h3><?=htmlspecialchars($d['document_name'])?></h3><p class="muted"><?=htmlspecialchars($d['original_name'])?> · <?=number_format(((int)$d['file_size'])/1048576,2)?> MB</p><a class="btn" href="?token=<?=urlencode($token)?>&download=<?=$d['id']?>">Download</a></div><?php endforeach;?></div></body></html>
